#include <bits/stdc++.h>
using namespace std;

struct Merchant { long long balance; bool hasLimit; long long limit; };
enum State { REQUIRES_ACTION, PROCESSING, COMPLETED };
struct Intent { string merchant; long long amount; State state; bool refunded; long long successTs; };

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int q = stoi(line);
    map<string, Merchant> merchants;
    unordered_map<string, Intent> intents;
    for (int i = 0; i < q && getline(cin, line); i++) {
        istringstream in(line);
        long long ts;
        string op;
        in >> ts >> op;
        vector<string> a;
        for (string t; in >> t;) a.push_back(t);
        if (op == "INIT") {
            if (!merchants.count(a[0]))
                merchants[a[0]] = {stoll(a[1]), a.size() > 2, a.size() > 2 ? stoll(a[2]) : 0};
        } else if (op == "CREATE") {
            long long amount = stoll(a[2]);
            if (!intents.count(a[0]) && merchants.count(a[1]) && amount >= 0)
                intents[a[0]] = {a[1], amount, REQUIRES_ACTION, false, 0};
        } else if (op == "ATTEMPT" || op == "SUCCEED" || op == "FAIL" || op == "UPDATE" || op == "REFUND") {
            auto it = intents.find(a[0]);
            if (it == intents.end()) continue;
            Intent &item = it->second;
            // Each transition applies only from its required state.
            if (op == "ATTEMPT" && item.state == REQUIRES_ACTION) item.state = PROCESSING;
            else if (op == "SUCCEED" && item.state == PROCESSING) {
                item.state = COMPLETED;
                merchants[item.merchant].balance += item.amount;
                item.successTs = ts;
            } else if (op == "FAIL" && item.state == PROCESSING) item.state = REQUIRES_ACTION;
            else if (op == "UPDATE" && item.state == REQUIRES_ACTION && stoll(a[1]) >= 0) item.amount = stoll(a[1]);
            else if (op == "REFUND" && item.state == COMPLETED && !item.refunded) {
                Merchant &m = merchants[item.merchant];
                if (!m.hasLimit || m.limit < 0 || (m.limit > 0 && ts - item.successTs <= m.limit)) {
                    m.balance -= item.amount;
                    item.refunded = true;
                }
            }
        }
    }
    string s = to_string(merchants.size()) + "\n";
    for (auto &[name, m] : merchants) s += name + " " + to_string(m.balance) + "\n";
    fwrite(s.data(), 1, s.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static class Merchant { long balance; boolean hasLimit; long limit; }
    static final int REQUIRES_ACTION = 0, PROCESSING = 1, COMPLETED = 2;
    static class Intent { String merchant; long amount; int state = REQUIRES_ACTION; boolean refunded; long successTs; }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        int q = Integer.parseInt(br.readLine().trim());
        TreeMap<String, Merchant> merchants = new TreeMap<>();
        HashMap<String, Intent> intents = new HashMap<>();
        for (int i = 0; i < q; i++) {
            String line = br.readLine();
            if (line == null) break;
            String[] p = line.trim().split("\\s+");
            long ts = Long.parseLong(p[0]);
            String op = p[1];
            if (op.equals("INIT")) {
                if (!merchants.containsKey(p[2])) {
                    Merchant m = new Merchant();
                    m.balance = Long.parseLong(p[3]);
                    m.hasLimit = p.length > 4;
                    if (m.hasLimit) m.limit = Long.parseLong(p[4]);
                    merchants.put(p[2], m);
                }
            } else if (op.equals("CREATE")) {
                long amount = Long.parseLong(p[4]);
                if (!intents.containsKey(p[2]) && merchants.containsKey(p[3]) && amount >= 0) {
                    Intent it = new Intent();
                    it.merchant = p[3];
                    it.amount = amount;
                    intents.put(p[2], it);
                }
            } else if (op.equals("ATTEMPT") || op.equals("SUCCEED") || op.equals("FAIL") || op.equals("UPDATE") || op.equals("REFUND")) {
                Intent item = intents.get(p[2]);
                if (item == null) continue;
                // Each transition applies only from its required state.
                if (op.equals("ATTEMPT") && item.state == REQUIRES_ACTION) item.state = PROCESSING;
                else if (op.equals("SUCCEED") && item.state == PROCESSING) {
                    item.state = COMPLETED;
                    merchants.get(item.merchant).balance += item.amount;
                    item.successTs = ts;
                } else if (op.equals("FAIL") && item.state == PROCESSING) item.state = REQUIRES_ACTION;
                else if (op.equals("UPDATE") && item.state == REQUIRES_ACTION && Long.parseLong(p[3]) >= 0) item.amount = Long.parseLong(p[3]);
                else if (op.equals("REFUND") && item.state == COMPLETED && !item.refunded) {
                    Merchant m = merchants.get(item.merchant);
                    if (!m.hasLimit || m.limit < 0 || (m.limit > 0 && ts - item.successTs <= m.limit)) {
                        m.balance -= item.amount;
                        item.refunded = true;
                    }
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(merchants.size()).append('\n');
        for (Map.Entry<String, Merchant> e : merchants.entrySet())
            sb.append(e.getKey()).append(' ').append(e.getValue().balance).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

type merchant struct {
	balance  int64
	hasLimit bool
	limit    int64
}

const (
	requiresAction = iota
	processing
	completed
)

type intent struct {
	merchant  string
	amount    int64
	state     int
	refunded  bool
	successTs int64
}

func atoi(s string) int64 { v, _ := strconv.ParseInt(s, 10, 64); return v }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Scan()
	q, _ := strconv.Atoi(strings.TrimSpace(sc.Text()))
	merchants := map[string]*merchant{}
	intents := map[string]*intent{}
	for i := 0; i < q && sc.Scan(); i++ {
		p := strings.Fields(sc.Text())
		ts, op := atoi(p[0]), p[1]
		switch op {
		case "INIT":
			if _, ok := merchants[p[2]]; !ok {
				m := &merchant{balance: atoi(p[3]), hasLimit: len(p) > 4}
				if m.hasLimit {
					m.limit = atoi(p[4])
				}
				merchants[p[2]] = m
			}
		case "CREATE":
			amount := atoi(p[4])
			_, dup := intents[p[2]]
			_, known := merchants[p[3]]
			if !dup && known && amount >= 0 {
				intents[p[2]] = &intent{merchant: p[3], amount: amount}
			}
		case "ATTEMPT", "SUCCEED", "FAIL", "UPDATE", "REFUND":
			item, ok := intents[p[2]]
			if !ok {
				continue
			}
			// Each transition applies only from its required state.
			switch {
			case op == "ATTEMPT" && item.state == requiresAction:
				item.state = processing
			case op == "SUCCEED" && item.state == processing:
				item.state = completed
				merchants[item.merchant].balance += item.amount
				item.successTs = ts
			case op == "FAIL" && item.state == processing:
				item.state = requiresAction
			case op == "UPDATE" && item.state == requiresAction && atoi(p[3]) >= 0:
				item.amount = atoi(p[3])
			case op == "REFUND" && item.state == completed && !item.refunded:
				m := merchants[item.merchant]
				if !m.hasLimit || m.limit < 0 || (m.limit > 0 && ts-item.successTs <= m.limit) {
					m.balance -= item.amount
					item.refunded = true
				}
			}
		}
	}
	names := make([]string, 0, len(merchants))
	for name := range merchants {
		names = append(names, name)
	}
	sort.Strings(names)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(names)) + "\n")
	for _, name := range names {
		w.WriteString(name + " " + strconv.FormatInt(merchants[name].balance, 10) + "\n")
	}
}
